( 256 256 0 ) ( 256 256 256 ) ( 256 272 256 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -256 272 0 ) ( -256 272 256 ) ( -256 256 256 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
}
// wall -Y
{
( 256 -256 256 ) ( 256 -272 256 ) ( -256 -272 256 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 256 -272 0 ) ( 256 -256 0 ) ( -256 -256 0 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
