// the "rock" - lower block. Stacked boxes rather than a sloped lump, because
// sloped faces are what the shading work actually wants and should be added in
// Radiant where they can be seen. These give hard edges to look at meanwhile.
{
( 96 96 96 ) ( 96 -96 96 ) ( -96 -96 96 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 96 -96 0 ) ( 96 96 0 ) ( -96 96 0 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 96 96 0 ) ( 96 96 96 ) ( -96 96 96 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -96 -96 0 ) ( -96 -96 96 ) ( 96 -96 96 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 96 -96 0 ) ( 96 -96 96 ) ( 96 96 96 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -96 96 0 ) ( -96 96 96 ) ( -96 -96 96 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
}
// the "rock" - upper block, offset so the silhouette has hard steps in it
{
( 64 48 160 ) ( 64 -64 160 ) ( -48 -64 160 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 64 -64 96 ) ( 64 48 96 ) ( -48 48 96 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 64 48 96 ) ( 64 48 160 ) ( -48 48 160 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -48 -64 96 ) ( -48 -64 160 ) ( 64 -64 160 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 64 -64 96 ) ( 64 -64 160 ) ( 64 48 160 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -48 48 96 ) ( -48 48 160 ) ( -48 -64 160 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
}
}
// entity 1 - the light this map exists to keep. Off to one side and high, so
// the rock is lit from a direction rather than from directly above, which is
// what makes faceting obvious.
{
"classname" "light"
"origin" "-160 -160 224"
"light" "600"
"_color" "1.0 0.95 0.85"
}
// entity 2 - a second, dimmer fill from the far side, so the shadowed faces are
// not pure black and the shading gradient is readable across the whole form
{
"classname" "light"
"origin" "192 192 200"
"light" "250"
"_color" "0.75 0.82 1.0"
}
// entity 3
{
"classname" "info_player_deathmatch"
"origin" "-192 -192 32"
"angle" "45"
}
